  .ribbon-control:hover { background: var(--bg-subtle); border-color: var(--border-default); }
  .ribbon-stack { display: grid; grid-template-columns: 96px 40px; gap: 4px; }
  .format-row { grid-column: 1 / -1; display: flex; gap: 2px; }
  .workspace { min-height: 620px; display: grid; grid-template-columns: minmax(0,1fr) 210px; background: var(--bg-canvas); }
