  .page { width: min(760px,100%); min-height: 500px; margin: 0 auto; padding: clamp(28px,5vw,58px); background: var(--bg-page); border: 1px solid var(--border-subtle); box-shadow: var(--shadow-page); }
  .doc-hero { padding: 4px 0 28px; border-bottom: 1px solid var(--border-default); }
  .doc-kicker { margin: 0 0 12px; color: var(--color-primary-500); font-size: 11px; font-weight: 700; letter-spacing: .11em; text-transform: uppercase; }
