  /* Semantic (다크 캔버스 위 가독) */
  --color-success-bg: #143A1A;
  --color-success-fg: #6CCB6C;
  --color-warning-bg: #3D3210;
  --color-warning-fg: #E5C158;
  --color-error-bg:   #4A1D20;
  --color-error-fg:   #E88A8F;
  --color-info-bg:    #16263F;
  --color-info-fg:    #6892C3;

  /* Tracked changes / Comments */
  --color-comment:    #E0A45A;        /* 주석 사이드바 */
  --color-revision:   #EC6A9C;        /* 변경 추적 */

  /* Surface */
  --bg-canvas:   #1F1F1F;             /* 캔버스(페이지 외부) */
  --bg-page:     #2A2A2A;             /* A4 페이지 */
  --bg-subtle:   #242424;
  --bg-ribbon:   #2C2C2C;
  --bg-overlay:  rgba(0,0,0,0.60);

  /* Text */
  --text-primary:    #F3F2F1;
  --text-secondary:  #D2D0CE;
  --text-tertiary:   #A19F9D;
  --text-link:       #6892C3;
  --text-on-primary: #1A1A1A;
  --text-disabled:   #6E6C6A;

  /* Border */
  --border-default: #3B3A39;
  --border-subtle:  #2F2F2F;
  --border-strong:  #5A5856;
  --border-focus:   #6892C3;
}

